import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [view, setView] = useState({ results: [], phase: "idle" });

  const valueRef = useRef("");
  const searchRef = useRef(search);
  const timerRef = useRef(null);
  const latestRef = useRef(null);
  const mountedRef = useRef(false);

  useEffect(() => {
    searchRef.current = search;
  }, [search]);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const reset = useCallback(() => {
    clearTimer();

    const previous = latestRef.current;
    latestRef.current = null;
    setView({ results: [], phase: "idle" });
    previous?.controller.abort();
  }, [clearTimer]);

  const startRequest = useCallback(
    async (query) => {
      if (!mountedRef.current) return;

      clearTimer();
      if (query.length < minChars) {
        reset();
        return;
      }

      const request = {
        query,
        controller: new AbortController(),
        phase: "pending",
      };

      const previous = latestRef.current;
      latestRef.current = request;
      setView((current) => ({
        results: current.results,
        phase: "pending",
      }));
      previous?.controller.abort();

      const isCurrent = () =>
        mountedRef.current &&
        latestRef.current === request &&
        !request.controller.signal.aborted;

      if (!isCurrent()) return;

      try {
        const performSearch = searchRef.current;
        const results = await performSearch(query, {
          signal: request.controller.signal,
        });

        if (!isCurrent()) return;

        request.phase = "success";
        setView({ results, phase: "success" });
      } catch (error) {
        if (!isCurrent()) return;

        if (error?.name === "AbortError") {
          request.phase = "aborted";
          setView((current) => ({
            results: current.results,
            phase: "idle",
          }));
        } else {
          request.phase = "error";
          setView({ results: [], phase: "error" });
        }
      }
    },
    [clearTimer, minChars, reset]
  );

  const schedule = useCallback(
    (rawValue) => {
      clearTimer();

      const query = rawValue.trim();
      if (query.length < minChars) {
        reset();
        return;
      }

      timerRef.current = setTimeout(() => {
        timerRef.current = null;

        const latest = latestRef.current;
        if (
          latest &&
          latest.query === query &&
          !latest.controller.signal.aborted &&
          (latest.phase === "pending" || latest.phase === "success")
        ) {
          return;
        }

        void startRequest(query);
      }, debounceMs);
    },
    [clearTimer, debounceMs, minChars, reset, startRequest]
  );

  useEffect(() => {
    mountedRef.current = true;

    return () => {
      mountedRef.current = false;
      clearTimer();

      const latest = latestRef.current;
      latestRef.current = null;
      latest?.controller.abort();
    };
  }, [clearTimer]);

  useEffect(() => {
    schedule(valueRef.current);
    return clearTimer;
  }, [clearTimer, schedule]);

  function handleChange(event) {
    const rawValue = event.target.value;
    valueRef.current = rawValue;
    setValue(rawValue);
    schedule(rawValue);
  }

  function handleRetry() {
    void startRequest(valueRef.current.trim());
  }

  const status =
    view.phase === "pending"
      ? "Searching..."
      : view.phase === "success" && view.results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{status}</div>
      <ul aria-label="Results">
        {view.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {view.phase === "error" && (
        <div role="alert">
          Something went wrong{" "}
          <button type="button" onClick={handleRetry}>
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
